WITH cs_agg AS (SELECT cs.cs_promo_sk, SUM(cs.cs_net_profit) AS cs_net_profit, SUM(cs.cs_quantity) AS cs_quantity, SUM(cs.cs_ext_discount_amt) AS cs_total_discount FROM catalog_sales cs GROUP BY cs.cs_promo_sk), ss_agg AS (SELECT ss.ss_promo_sk, ss.ss_store_sk, SUM(ss.ss_net_profit) AS ss_net_profit, SUM(ss.ss_quantity) AS ss_quantity, SUM(ss.ss_ext_discount_amt) AS ss_total_discount FROM store_sales ss GROUP BY ss.ss_promo_sk, ss.ss_store_sk), promo_store AS (SELECT p.p_promo_sk, p.p_promo_id, p.p_promo_name, s.s_store_sk, s.s_store_name, s.s_floor_space FROM promotion p JOIN store_sales ss ON p.p_promo_sk = ss.ss_promo_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk GROUP BY p.p_promo_sk, p.p_promo_id, p.p_promo_name, s.s_store_sk, s.s_store_name, s.s_floor_space) SELECT ps.p_promo_id, ps.p_promo_name, ps.s_store_name, (COALESCE(cs.cs_net_profit,0) + COALESCE(ssa.ss_net_profit,0)) AS total_net_profit, (COALESCE(cs.cs_quantity,0) + COALESCE(ssa.ss_quantity,0)) AS total_quantity, CASE WHEN (COALESCE(cs.cs_net_profit,0) + COALESCE(ssa.ss_net_profit,0)) > 100000 THEN 'HIGH' WHEN (COALESCE(cs.cs_net_profit,0) + COALESCE(ssa.ss_net_profit,0)) BETWEEN 50000 AND 100000 THEN 'MEDIUM' ELSE 'LOW' END AS profit_category, RANK() OVER (ORDER BY (COALESCE(cs.cs_net_profit,0) + COALESCE(ssa.ss_net_profit,0)) DESC) AS profit_rank FROM promo_store ps LEFT JOIN cs_agg cs ON cs.cs_promo_sk = ps.p_promo_sk LEFT JOIN ss_agg ssa ON ssa.ss_promo_sk = ps.p_promo_sk AND ssa.ss_store_sk = ps.s_store_sk ORDER BY profit_rank LIMIT 20
